import{z as l,x as d,o as E,c as B,q as t,j as n,D as e,d as r,s as o,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"闪存对照","description":"","frontmatter":{"title":"闪存对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/flash-memory.md","filePath":"cs/flash-memory.md","lastUpdated":1791413859000}'),D={name:"cs/flash-memory.md"};function p(m,a,h,c,R,C){const s=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=t('<h1 id="闪存对照" tabindex="-1">闪存对照 <a class="header-anchor" href="#闪存对照" aria-label="Permalink to &quot;闪存对照&quot;">​</a></h1><div class="epigraph"><p>DRAM 靠电容、掉电即忘；闪存把电荷关进浮栅，不刷新也能留，但写是按块擦再编程，不能当随机存取的主存。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/dram-refresh">DRAM 刷新</a>钉死了易失阵列的周期性读回写。本课不重推保留时间，也不从文件系统 FTL 另起。缺口是对照：<strong>非易失</strong>如何进组成课——能当 BIOS/盘，不能替换那套需刷新的主存时序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浮栅（或电荷陷阱）存 0/1，读近似随机；写前通常要擦除，擦除粒度是块，远大于字。编程电压高、次数有限（磨损）。缺口不是半导体工艺步骤，而是与 SRAM/DRAM 的角色划分：片上 SRAM 快且易失，DRAM 主存要刷新，闪存作外存或片上 ROM 替代，接口是命令队列而不是「地址一到数据就稳」。</p><p><span class="marginnote">术语翻译：浮栅就是「被绝缘层包住、电荷跑不出去的小笼子」——写入时用高压把电子泵进笼子，断电后电荷仍留在原地，这就是非易失的物理来源；读的时候看这个笼子有没有把晶体管的阈值电压扳动。</span></p><p>NOR 可按字节读、便于原地执行；NAND 密度高、按页读，作 SSD。本课点到，不把通道、磨损均衡写成 OS 课。</p><h3 id="闪存不是「不需要刷新的-dram」" tabindex="-1">闪存不是「不需要刷新的 DRAM」 <a class="header-anchor" href="#闪存不是「不需要刷新的-dram」" aria-label="Permalink to &quot;闪存不是「不需要刷新的 DRAM」&quot;">​</a></h3><p>随机写延迟与寿命模型完全不同。把闪存插进单周期数据存储器框，关键路径与磨损都会说错。掉电保存不等于可以当寄存器。</p><p><span class="marginnote">Harris 把非易失列为另一类存储器。Patterson/Hennessy 用磁盘/闪存当存储层次底层。控制器常有独立时钟，<a href="/cs/clock-domain">下一课</a>的跨域从这里开始有实物。</span></p><p><span class="marginnote">数字实例：一页常为 4-16 KB，一块含几十到几百页，比如 64 页 × 4 KB = 256 KB。只想改某页里的 1 个字节，也得先擦掉整块 256 KB、再把原块内容搬回去——擦除粒度是「想写的粒度」的几十倍，这就是「不能原地改」的量化含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：选字线，阈值电压判决。写：先擦块再编程页。CPU 经控制器发命令，完成以中断或轮询通知——中断入口很后才讲，本课只承认「多拍、另一时钟」。</p>',13)),(E(),n(i,null,{default:e(()=>[o(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRAM%5B%22SRAM%EF%BC%9A%E9%9D%99%E6%80%81%E3%80%81%E8%B4%B5%22%5D%20--%3E%20DRAM%5B%22DRAM%EF%BC%9A%E5%AF%86%E3%80%81%E8%A6%81%E5%88%B7%E6%96%B0%22%5D%0A%20%20DRAM%20--%3E%20FLASH%5B%22%E9%97%AA%E5%AD%98%EF%BC%9A%E9%9D%9E%E6%98%93%E5%A4%B1%E3%80%81%E5%9D%97%E6%93%A6%22%5D%0A%20%20FLASH%20--%3E%20ROLE%5B%22%E5%A4%96%E5%AD%98%20%2F%20%E4%BB%A3%E7%A0%81%20ROM%22%5D%0A%20%20ROLE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%97%B6%E9%92%9F%E5%9F%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[r("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"存储程序的指令可以放在 NOR 闪上直接取指（片上 MCU），或先拷到 SRAM/DRAM。后课冯·诺依曼图里的「存储器」教学上仍是 DRAM/SRAM；闪存在层次最底下。刷新义务没有了，换成磨损与擦除。",-1)),(E(),n(i,null,{default:e(()=>[o(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%94%B9%E5%86%99%E4%B8%80%E9%A1%B5%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20E%7B%22%E7%9B%AE%E6%A0%87%E5%9D%97%E5%B7%B2%E6%93%A6%E9%99%A4%3F%22%7D%0A%20%20E%20--%3E%7C%22%E5%90%A6%22%7C%20ER%5B%22%E6%95%B4%E5%9D%97%E6%93%A6%E9%99%A4%3A%20%E5%85%A8%E9%83%A8%E4%BD%8D%E5%A4%8D%E4%BD%8D%2C%20%E6%85%A2%E4%B8%94%E8%AE%A1%E5%85%A5%E7%A3%A8%E6%8D%9F%22%5D%0A%20%20E%20--%3E%7C%22%E6%98%AF%22%7C%20P%5B%22%E6%8C%89%E9%A1%B5%E7%BC%96%E7%A8%8B%3A%20%E5%8F%AA%E8%83%BD%E6%8A%8A%201%20%E5%86%99%E6%88%90%200%22%5D%0A%20%20ER%20--%3E%20P%0A%20%20P%20--%3E%20RD%5B%22%E8%AF%BB%3A%20%E9%80%89%E5%AD%97%E7%BA%BF%2C%20%E6%8C%89%E9%98%88%E5%80%BC%E7%94%B5%E5%8E%8B%E5%88%A4%200%2F1%22%5D%0A%20%20RD%20--%3E%20OK%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%E4%BB%A5%E4%B8%AD%E6%96%AD%E9%80%9A%E7%9F%A5%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">常见误区：初学者以为「掉电不丢 = 可以随便当内存用」。闪存随机写比读慢百倍千倍，擦写次数有限（TLC 常以千次计），高频小写入很快磨穿介质。所以 SSD 要靠 FTL 做磨损均衡，主存也始终不会换成闪存。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 3D NAND 层数、不把光刻产线请进来。不讨论文件系统日志。EEPROM 字节可改是同一非易失家族的小容量形态。</p><p>后课默认：主存仍是 DRAM（加刷新）；闪存是非易失外存或 ROM；其控制器时钟可与 CPU 无关。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>闪存非易失，写按块擦、有磨损。</li><li>不能当 DRAM 的免刷新版主存。</li><li>控制器可能独立于 CPU 时钟，交给时钟域课。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',6))])}const M=l(D,[["render",p]]);export{u as __pageData,M as default};
